\section{Introduction}

\subsection{The empirical situation}

A recurring quantity in the deployment of autoregressive sequence models is the \emph{attention
budget}: the number of past positions whose key--value pairs must be retained so that a prescribed
fraction of attention mass is preserved. At a given context length one sorts the attention weights
in decreasing order, lets $f(k)$ denote the mass captured by the top $k$ of them, fixes a gate
$\tau$ (here $\tau=0.98$), and asks for
\[
\kstar \;=\; \min\{\, k\in\NN : f(k)\ge\tau \,\}.
\]
Since $f$ is nondecreasing and tends to $1$, this minimum exists and is the operationally relevant
integer: it is the cache size one ships.

A sequence of measurements on a half-billion-parameter model produced an apparent inconsistency.
Sweeping budgets over the doubling ladder $4,8,16,32,\dots$ at context $1024$ returned $32$. A later
sweep, on the same model, corpus, gate and harness, over the arithmetic set $\{4,8,12,20,24\}$,
returned $20$. Neighbouring context lengths $512$ and $2048$ returned $16$ and $24$; a second corpus
at context $2048$ returned $32$, which had been read as evidence of corpus sensitivity.

The thesis of this paper is that none of these discrepancies requires an empirical explanation.
Each is the exact, predictable output of an arithmetic operator applied to an unknown but fixed
truth --- and once that operator is identified, one can say in advance which claims a given sweep
is capable of supporting and which it is not.

\subsection{Contributions}

\begin{enumerate}[label=(\arabic*)]
\item The Measurement Theorem (\S3): a grid measurement of a monotone threshold is \emph{identically}
the grid-rounding of the true knee.
\item Structure and uniqueness of the read-out (\S2, \S3.3).
\item Exactness criteria (\S4): divisibility for arithmetic grids, base-two digit sum for the doubling
grid; the explicit overstatement $2^{e+1}-k$; octave collapse.
\item Analysis of the five-point table (\S5): forced reading $20$; tight bracket $(12,20]$;
underdetermination at $16$.
\item Resolution counting and design (\S6): $\lfloor N/d\rfloor$ versus $\log_2 N+1$; the verdict
bound; divisor-function resolution power; the gcd design principle.
\item A unifying bridge (\S7): binary staircase numbers with at least two ones are always read as
their ceiling power of two.
\end{enumerate}

\section{Grids and the reading operator}

\begin{definition}[Sweep grid]
A \emph{sweep grid} is a set $G\subseteq\NN$ that is unbounded: for every $n$ there is $m\in G$ with
$n\le m$. We write $G_{\ge k}=\{g\in G: g\ge k\}$, which is nonempty by unboundedness.
\end{definition}

\begin{definition}[Reading]
The \emph{grid reading} of $k\in\NN$ is $\rd_G(k)=\min G_{\ge k}=\min\{g\in G: k\le g\}$.
\end{definition}

\begin{definition}
For $d\ge 1$ the \emph{arithmetic grid} is $A_d=\{n: d\mid n\}$; the \emph{dyadic grid} is
$D=\{2^e: e\ge 0\}$. Both are unbounded, since $dn\ge n$ and $2^n>n$.
\end{definition}

\begin{proposition}[Basic properties]\label{prop:basic}
For every grid $G$:
\begin{enumerate}[label=(\roman*)]
\item $\rd_G(k)\in G$ and $k\le \rd_G(k)$ \emph{(inflationary: a sweep never under-reports)};
\item if $g\in G$ and $k\le g$ then $\rd_G(k)\le g$ \emph{(minimality)};
\item $\rd_G(k)=k \iff k\in G$ \emph{(fixed points)};
\item $k\le k' \implies \rd_G(k)\le \rd_G(k')$ \emph{(monotonicity)};
\item $\rd_G(\rd_G(k))=\rd_G(k)$ \emph{(idempotence)};
\item if $H\subseteq G$ then $\rd_G(k)\le \rd_H(k)$ \emph{(refinement never inflates)}.
\end{enumerate}
\end{proposition}

\begin{proof}
(i) and (ii) are the defining properties of the least element of $G_{\ge k}$. (iii): if
$\rd_G(k)=k$ then $k\in G$ by (i); conversely $k\in G$ gives $k\in G_{\ge k}$, so $\rd_G(k)\le k$ by
(ii), and $\ge$ by (i). (iv): $\rd_G(k')\in G$ dominates $k'\ge k$; apply (ii). (v) is (iii) applied
to $\rd_G(k)\in G$. (vi): $\rd_H(k)\in H\subseteq G$ dominates $k$; apply (ii).
\end{proof}

Items (i), (iv), (v) say that $\rd_G$ is a \emph{closure operator} on $(\NN,\le)$, and (iii)
identifies its closed elements as $G$.

\begin{proposition}[Collapse]\label{prop:collapse}
If $k\le k'$ and $k'\le \rd_G(k)$ then $\rd_G(k)=\rd_G(k')$.
\end{proposition}

\begin{proof}
Monotonicity gives $\le$; and $\rd_G(k)\in G$ dominates $k'$, so minimality gives $\ge$.
\end{proof}

\begin{corollary}[Coarsening never invents separation]
If $\rd_G(k)<\rd_G(k')$ then $k<k'$.
\end{corollary}

\section{The Measurement Theorem}

\begin{theorem}[Measurement Theorem]\label{thm:measure}
Let $(\alpha,\le)$ be a linear order, $f:\NN\to\alpha$ nondecreasing, and $\tau\in\alpha$ with
$f(k)\ge\tau$ for some $k$. Put $\kstar=\min\{k: f(k)\ge\tau\}$. Then for every sweep grid $G$,
\[
\min\{\, g\in G: f(g)\ge\tau \,\} \;=\; \rd_G(\kstar).
\]
\end{theorem}

\begin{proof}
It suffices to show $\{g\in G: f(g)\ge\tau\}=G_{\ge \kstar}$. If $g\in G$ and $f(g)\ge\tau$ then $g$
lies in the set defining $\kstar$, so $\kstar\le g$. Conversely if $g\in G$ and $\kstar\le g$, then
$f(g)\ge f(\kstar)\ge\tau$ by monotonicity. Taking minima gives the claim.
\end{proof}

\begin{corollary}[Exactness]
The swept measurement equals $\kstar$ if and only if $\kstar\in G$.
\end{corollary}

\begin{corollary}[Monotone refinement]\label{cor:refine}
If $H\subseteq G$ then the $G$-sweep never reports a larger knee than the $H$-sweep. When a fine and
a coarse sweep of the same profile disagree, the fine value is the smaller, and the difference is
entirely accounted for by the grid gap.
\end{corollary}

\begin{remark}[Attention budgets]
If $w$ is a positive weight sequence on a window of length $n$ and $\mathrm{retained}(w,n,k)$ is the
fraction of total weight carried by the $k$ largest entries, then $k\mapsto\mathrm{retained}(w,n,k)$
is nondecreasing and reaches any gate $\tau\le1$. Theorem~\ref{thm:measure} therefore applies
verbatim: a top-$k$ sweep restricted to $G$ reports $\rd_G(\kstar)$. Nothing about attention beyond
monotonicity is used.
\end{remark}

\subsection{Uniqueness of the read-out}

\begin{theorem}[Uniqueness]\label{thm:unique}
Let $G$ be a sweep grid and $M:\NN\to\NN$ satisfy: (i) $k\le M(k)$; (ii) $M$ monotone;
(iii) $M(M(k))=M(k)$; (iv) $M(k)=k\iff k\in G$. Then $M=\rd_G$.
\end{theorem}

\begin{proof}
Fix $k$. By (iii), $M(k)$ is a fixed point, so $M(k)\in G$ by (iv); with (i) and minimality,
$\rd_G(k)\le M(k)$. Conversely $\rd_G(k)\in G$, so $M(\rd_G(k))=\rd_G(k)$ by (iv); monotonicity on
$k\le\rd_G(k)$ gives $M(k)\le \rd_G(k)$.
\end{proof}

Any proposed read-out must therefore violate one of the four axioms: it must sometimes under-report,
or be non-monotone, or be unstable under re-measurement, or be inexact at a point that was actually
measured. Each is a substantive modelling commitment, not a free improvement.

\section{Exactness criteria for the two grid families}

\begin{proposition}\label{prop:arith}
For $d\ge1$: $\rd_{A_d}(k)=k\iff d\mid k$, and explicitly $\rd_{A_d}(k)=d\lceil k/d\rceil$.
\end{proposition}

\begin{corollary}
For $k\ne0$, the step-$4$ sweep resolves $k$ iff $v_2(k)\ge2$, where $v_2$ is the $2$-adic
valuation: $k$ must end in at least two binary zeros.
\end{corollary}

\begin{theorem}[Dyadic reading]\label{thm:dyadread}
$\rd_D(k)=2^{\lceil\log_2 k\rceil}$ for all $k$.
\end{theorem}

\begin{proof}
$k\le 2^{\lceil\log_2 k\rceil}$ and this is a grid point, so $\rd_D(k)\le 2^{\lceil\log_2 k\rceil}$.
Conversely, writing $\rd_D(k)=2^j$ we have $k\le 2^j$, hence $\lceil\log_2 k\rceil\le j$ and
$2^{\lceil\log_2 k\rceil}\le 2^j=\rd_D(k)$.
\end{proof}

\begin{theorem}[Digit-sum criterion]\label{thm:digitsum}
For $k\ne0$: $\rd_D(k)=k$ if and only if the base-two digit sum of $k$ equals $1$, i.e.\ $k$ is a
power of two.
\end{theorem}

\begin{proof}
Powers of two have digit sum $1$. Conversely argue by strong induction. If $k$ is even, $k=2t$ with
$t\ne0$; the binary expansion of $k$ is that of $t$ with a $0$ appended, so the digit sums agree and
$t=2^e$ by induction, giving $k=2^{e+1}$. If $k$ is odd its last digit is $1$, so the digits of
$\lfloor k/2\rfloor$ sum to $0$; a nonzero number has nonzero leading digit and hence positive digit
sum, so $\lfloor k/2\rfloor=0$ and $k=1=2^0$.
\end{proof}

Since $16=10000_2$, $20=10100_2$, $24=11000_2$ have digit sums $1,2,2$, a doubling sweep resolves
$16$ and necessarily misreads $20$ and $24$.

\begin{theorem}[Explicit overstatement]\label{thm:overstate}
If $2^e<k\le 2^{e+1}$ then $\rd_D(k)=2^{e+1}$; the doubling sweep overstates the budget by exactly
$2^{e+1}-k$.
\end{theorem}

\begin{corollary}[Octave collapse]\label{cor:octave}
If $2^e<k\le k'\le 2^{e+1}$ then $\rd_D(k)=\rd_D(k')$: no doubling sweep can separate two knees in
one octave.
\end{corollary}

Hence $\rd_D(16)=16$, $\rd_D(20)=32$, $\rd_D(24)=32$, with overstatements $0$, $12$ and $8$ keys. The
dyadic image of the chain $16<20<24$ is $16,32,32$; the earlier ``context $1024\mapsto32$'' and the
``second corpus at $2048\mapsto32$'' are the same rounding event, and by Corollary~\ref{cor:octave}
the collapse is forced.

\section{The five-point table: what it determines and what it does not}

\begin{definition}\label{def:matching}
A function $f:\NN\to\QQ$ is \emph{table-matching} if it is nondecreasing and
\[
f(4)=0.8940,\quad f(8)=0.9520,\quad f(12)=0.9662,\quad f(20)=0.9803,\quad f(24)=0.9851 .
\]
The gate is $\tau=0.98$, the swept set is $S=\{4,8,12,20,24\}$, the \emph{true knee} is
$\kstar(f)=\min\{k: f(k)\ge\tau\}$ and the \emph{measured knee} is $m(f)=\min\{g\in S: f(g)\ge\tau\}$.
\end{definition}

Note $f(12)=0.9662<0.98\le0.9803=f(20)$; these two inequalities carry the whole analysis.

\begin{theorem}[Forced reading]\label{thm:forced}
Every table-matching $f$ satisfies $m(f)=20$.
\end{theorem}

\begin{proof}
$20\in S$ and $f(20)\ge\tau$, so $m(f)$ exists and $m(f)\le20$. As an element of $S$,
$m(f)\in\{4,8,12,20,24\}$; the values $0.8940,0.9520,0.9662$ lie below $0.98$, excluding $4,8,12$;
and $24>20\ge m(f)$ excludes $24$.
\end{proof}

\begin{theorem}[Bracket]\label{thm:bracket}
Every table-matching $f$ satisfies $12<\kstar(f)\le20$.
\end{theorem}

\begin{proof}
$f(20)\ge\tau$ gives $\kstar(f)\le20$. If $\kstar(f)\le12$ then monotonicity gives
$\tau\le f(\kstar(f))\le f(12)=0.9662<\tau$, a contradiction.
\end{proof}

\begin{definition}[Step witnesses]
For $t\in\NN$ put
\[
P_t(k)=\begin{cases}
0 & k<4,\\
0.8940 & 4\le k<8,\\
0.9520 & 8\le k<12,\\
0.9662 & 12\le k<t,\\
0.9803 & t\le k<24,\\
0.9851 & 24\le k.
\end{cases}
\]
\end{definition}

\begin{lemma}\label{lem:Pmono}
$P_t$ is nondecreasing for every $t$, and table-matching whenever $12<t\le20$.
\end{lemma}

\begin{proof}
The listed values are nondecreasing and the branch conditions are nested, so $a\le b$ places $a$ in a
branch no later than $b$. For matching with $12<t\le20$: $4$ falls in the second branch, $8$ in the
third, $12$ in the fourth (as $12<t$), $20$ in the fifth (as $t\le20<24$) and $24$ in the last.
\end{proof}

\begin{lemma}\label{lem:Pknee}
For $12<t\le20$, $\kstar(P_t)=t$.
\end{lemma}

\begin{proof}
$P_t(t)=0.9803\ge\tau$, so $\kstar\le t$; and $P_t(k)\le0.9662<\tau$ for every $k<t$.
\end{proof}

\begin{theorem}[Tightness]\label{thm:tight}
For every integer $t$ with $12<t\le20$ there is a table-matching profile whose true knee is exactly
$t$ and whose measured knee is $20$.
\end{theorem}

\begin{proof}
Take $P_t$ and combine Lemmas~\ref{lem:Pmono}, \ref{lem:Pknee} with Theorem~\ref{thm:forced}.
\end{proof}

\begin{corollary}[Underdetermination]\label{cor:under}
There exist table-matching $f,g$ with $m(f)=m(g)=20$ but $\kstar(f)=16\ne20=\kstar(g)$.
\end{corollary}

The reason is structural: $S$ contains no point strictly between $12$ and $20$, and in particular
omits $16$, the value reported at the neighbouring context length $512$.

\begin{theorem}[Two-valued fine rounding]\label{thm:twovalued}
For every table-matching $f$, $\rd_{A_4}(\kstar(f))\in\{16,20\}$, and it equals $20$ precisely when
$\kstar(f)>16$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:bracket}, $13\le\kstar\le20$. If $\kstar\le16$ then $16\in A_4$ dominates
$\kstar$, so the reading is $\le16$; being a multiple of $4$ that is $\ge13$, it is exactly $16$.
If $\kstar>16$ the same argument with $20$ gives the reading $20$.
\end{proof}

\subsection{What survives}

\begin{itemize}
\item \textbf{Certified.} At context $1024$, $20$ keys clear the $0.98$ gate and $12$ do not. This is
Theorem~\ref{thm:forced}, and is exactly the deployment-facing statement; it justifies moving the
shipped entry for context $1024$ from $32$ keys to $20$.
\item \textbf{Certified.} The earlier value $32$ is a rounding of the same truth, by
Theorem~\ref{thm:measure} with Theorem~\ref{thm:overstate}.
\item \textbf{Not certified.} That the chain $16<20<24$ across contexts $\{512,1024,2048\}$ is
strictly increasing: by Corollary~\ref{cor:under} the middle entry may equal $16$. Settling it
requires the single missing measurement at $k=16$, context $1024$.
\end{itemize}

\section{How much a sweep can resolve}

\begin{definition}
For a grid $G$ and $N\in\NN$ let $R_G(N)=\{k\in(0,N]: \rd_G(k)=k\}=(0,N]\cap G$.
\end{definition}

\begin{theorem}[Arithmetic count]
$|R_{A_d}(N)|=\lfloor N/d\rfloor$.
\end{theorem}

\begin{theorem}[Dyadic count]
$|R_D(N)|\le\log_2 N+1$.
\end{theorem}

\begin{proof}
$k\mapsto\lfloor\log_2 k\rfloor$ is injective on powers of two and maps $R_D(N)$ into
$\{0,\dots,\lfloor\log_2 N\rfloor\}$.
\end{proof}

\begin{theorem}[The fine grid wins from $N=32$]
For $m\ge5$, $|R_D(2^m)|<|R_{A_4}(2^m)|$.
\end{theorem}

\begin{proof}
Write $m=j+2$ with $j\ge3$. Then $|R_{A_4}(2^{j+2})|=2^j$ while $|R_D(2^{j+2})|\le j+3$, and
$j+3<2^j$ for $j\ge3$ by induction (base $6<8$; the inductive step doubles the right side while
adding one to the left).
\end{proof}

\begin{theorem}[Verdict bound]\label{thm:verdict}
The image $\{\rd_D(k): 0<k\le N\}$ has at most $\lceil\log_2 N\rceil+1$ elements.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:dyadread} each reading is $2^{\lceil\log_2 k\rceil}$ with
$\lceil\log_2 k\rceil\le\lceil\log_2 N\rceil$.
\end{proof}

\begin{corollary}[Forced plateaus]
A chain of $r$ true knees in $(0,N]$ reported by a doubling sweep contains at least
$r-\lceil\log_2 N\rceil-1$ repeated values: apparent flatness in a long coarse chain is a counting
artifact, prior to any modelling assumption.
\end{corollary}

\begin{theorem}[Resolution is divisibility]
For $k\ne0$ and $d\ge1$, the step-$d$ sweep resolves $k$ iff $d\in\Div(k)$; hence the number of
arithmetic sweeps resolving $k$ is the divisor-counting function $\tau(k)$.
\end{theorem}

Along the reported chain $\tau(16)=5$, $\tau(20)=6$, $\tau(24)=8$; but this trend is accidental.

\begin{proposition}[Non-monotonicity]
$\tau(28)=6<8=\tau(24)$ although $24<28$: a finer grid does not monotonically buy resolution.
\end{proposition}

\begin{theorem}[gcd design principle]\label{thm:gcd}
Let $K\subseteq\NN$ be a finite chain of knees and $d\ge1$. The step-$d$ sweep resolves every element
of $K$ if and only if $d\mid\gcd K$.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:arith} the left side says $d\mid k$ for all $k\in K$, which is exactly
$d\mid\gcd K$ by the universal property of the gcd.
\end{proof}

\begin{corollary}[The step-$4$ grid is forced]
A step-$d$ sweep resolves all of $16,20,24$ iff $d\mid4$. Since $\gcd\{16,20,24\}=4$, step $4$ is the
coarsest arithmetic sweep seeing the whole chain, and every coarser one misreads a cell; the doubling
ladder's local steps $8,16,32$ do not divide $4$.
\end{corollary}

\begin{proof}
If $d\mid16$ and $d\mid20$ then $d\mid20-16=4$; conversely $4$ divides each of $16,20,24$.
\end{proof}

\section{One mechanism: binary staircase knees}

\begin{definition}[Binary staircase]
For $b,j\in\NN$ set $s(b,j)=2^b(2^j-1)$: in binary, $j$ ones followed by $b$ zeros. It satisfies the
complement identity $s(b,j)+2^b=2^{b+j}$.
\end{definition}

\begin{theorem}[Staircase reading]\label{thm:stair}
For all $b$ and all $j\ge2$, $\rd_D\big(s(b,j)\big)=2^{b+j}$.
\end{theorem}

\begin{proof}
By the complement identity $s(b,j)=2^{b+j}-2^b$. Since $j\ge2$ we have $2^b<2^{b+j-1}$, hence
\[
2^{b+j-1}=2^{b+j}-2^{b+j-1}<2^{b+j}-2^{b}=s(b,j)\le 2^{b+j},
\]
so $s(b,j)$ lies strictly inside the top octave below $2^{b+j}$, and Theorem~\ref{thm:overstate}
gives the reading $2^{b+j}$.
\end{proof}

Thus every binary staircase number with at least two ones is misread by a doubling sweep as its
ceiling power of two.

\begin{corollary}
$112=2^4(2^3-1)=s(4,3)$, so $\rd_D(112)=2^7=128$. Together with
$\rd_D(20)=2^{\lceil\log_2 20\rceil}=32$, the two reported misreadings exhibit a single mechanism.
\end{corollary}

\section{Algorithms}

\textbf{Algorithm A (Grid reading).} For $A_d$ return $d\lceil k/d\rceil$ in $O(1)$ arithmetic
operations; for $D$ return $2^{\lceil\log_2 k\rceil}$ in $O(\log k)$ bit operations, or with a single
leading-zero-count instruction.

\textbf{Algorithm B (Sweep and read).} Given a monotone oracle for $f$, a gate $\tau$ and a finite
sweep set $S=\{g_1<\dots<g_r\}$, evaluate in increasing order and return the first point clearing
$\tau$: $r$ oracle calls, reducible to $\lceil\log_2 r\rceil$ by binary search, with the same answer
by Theorem~\ref{thm:measure}.

\textbf{Algorithm C (Bracket certificate).} Return $(g_{i-1},g_i]$ where $g_i$ is the first passing
and $g_{i-1}$ the last failing swept point. By Theorem~\ref{thm:bracket} this contains $\kstar$, and
by Theorem~\ref{thm:tight} every member of it is realised by a matching profile: the certificate is
sound \emph{and} complete, and is the strongest inference the data licenses.

\textbf{Algorithm D (Chain-resolving grid design).} Given a hypothesised chain $K$ and a window $N$,
compute $d=\gcd K$ by the Euclidean algorithm in $O(|K|\log\max K)$ steps and return
$\{d,2d,\dots\}\cap(0,N]$, of size $\lfloor N/d\rfloor$. By Theorem~\ref{thm:gcd} this is the
coarsest arithmetic sweep resolving every cell of $K$.

\section{Discussion, applications and open problems}

\subsection{Methodological consequences}
\begin{enumerate}[label=(\arabic*)]
\item \emph{Report brackets, not points.} A sweep yields $(g_{i-1},g_i]$; the point value $g_i$ is a
rounding.
\item \emph{Check grid holes against the claim.} Before asserting a strict chain, verify that each
cell's bracket excludes the neighbouring cell's value. Here $16\in(12,20]$, which invalidates the
strictness claim while leaving the deployment claim intact.
\item \emph{Disagreements between nested grids are not evidence.} By Corollary~\ref{cor:refine} the
finer sweep always reports the smaller value.
\item \emph{Design by gcd.} The sweep step should divide the gcd of the hypothesised chain; conversely
the step upper-bounds the granularity of any chain claim.
\end{enumerate}

\subsection{Applications beyond attention budgets}
The hypotheses are minimal --- a nondecreasing profile and a gate --- so the theory applies to any
first-crossing measurement sampled on a restricted set: minimum cache or batch size, minimum rank for
a target reconstruction error, minimum bit-width for a target accuracy loss; scaling-law breakpoints
measured on doubling ladders (which by Theorem~\ref{thm:verdict} can emit only $O(\log N)$ distinct
verdicts); empirical algorithmic phase transitions on geometric size ladders; and dose--response or
detection limits measured by serial dilution, where reported titres are literally grid readings. In
each case a reported breakpoint that is a power of two conveys strictly less information than one
that is not, since only the latter cannot have come from a doubling sweep.

\subsection{Limits}
The theory is deliberately noise-free. Real measurements average over finitely many windows and carry
sampling error, which can make the observed profile non-monotone near the gate; the correct extension
studies the distribution of $\rd_G(\hat\kstar)$, which inherits an inflationary bias. Second, grids
are treated order-theoretically and cost-free, whereas evaluating a large budget may be more expensive
than a small one; a weighted version of the design problem is open.

\subsection{Open problems}

\begin{problem}[Budgeted grid optimality: additive versus multiplicative loss]
Fix a window $[1,N]$ and $r$ sweep points. Conjecturally the sweep minimising the worst-case additive
overstatement $\max_k(\rd_G(k)-k)$ is the arithmetic grid of step $\lceil N/r\rceil$, while the sweep
minimising the worst-case multiplicative overstatement $\max_k \rd_G(k)/k$ is the geometric grid of
ratio $N^{1/r}$ (rounded to integers). The doubling grid would then be optimal for the wrong loss
function, which is exactly why it misreports knees by up to a factor $2$ while costing only
$\log_2 N$ points. The counting results of \S6 quantify both families; the optimisation should follow
from an exchange argument on gap lengths.
\end{problem}

\begin{problem}[Octave-collapse bound on certifiable chain length]
If a knee chain $k_1<\dots<k_r$ lies in $[1,N]$, a doubling sweep reports at most
$\lceil\log_2 N\rceil+1$ distinct values, so for $r>\lceil\log_2 N\rceil+1$ at least
$r-\lceil\log_2 N\rceil-1$ reported plateaus are artifacts. Conjecturally the number of genuine strict
increases such a sweep can certify equals the number of octaves the chain meets, minus one.
\end{problem}

\begin{problem}[Adaptive sweeps]
Binary search locates $\kstar$ exactly in $\lceil\log_2 N\rceil$ evaluations, beating every fixed grid
of comparable size. Formalise the trade-off between comparability of a fixed sweep across conditions
and resolution within a condition, and find the optimal partially adaptive scheme.
\end{problem}

\begin{problem}[Noisy readings]
With $f$ observed with error, characterise the bias and variance of the grid reading and determine
the grid minimising mean-squared error of the reported knee at fixed evaluation budget.
\end{problem}

\subsection{Conclusion}
A measurement made on a grid is the grid-rounding of the truth --- exactly, always, and provably. This
identity dissolves the apparent inconsistency between a doubling sweep reporting $32$ and a step-$4$
sweep reporting $20$: they are two readings of one number. It certifies the operational conclusion
(twenty keys suffice, twelve do not) while refuting a stronger claim built upon it (that the
cross-context chain is strictly increasing), because the fine grid has a hole exactly where the
decisive comparison lives. And it turns sweep design into arithmetic: divisibility decides exactness,
binary weight decides whether a doubling sweep can ever be right, the divisor function counts how many
sweeps can see a budget, and the greatest common divisor of a hypothesised chain names the coarsest
sweep that can certify it.

