function READ_ARITHMETIC(d, k):
    require d >= 1
    if k <= 0: return 0
    return d * ceil(k / d)            # least multiple of d that is >= k

function READ_DYADIC(k):
    if k <= 1: return 1
    e <- 0
    while 2^e < k:                    # e ends at ceil(log2 k)
        e <- e + 1
    return 2^e

function IS_EXACT(grid, k):
    # exactness criteria, no sweep required
    if grid is arithmetic with step d: return (d divides k)
    if grid is dyadic:                 return (binary digit sum of k equals 1)

function OVERSTATEMENT(grid, k):
    return READ(grid, k) - k          # 0 iff k lies on the grid

