from typing import List


def read_arith(d: int, k: int) -> int:
    """Least multiple of d that is >= k."""
    if d <= 0:
        raise ValueError("step must be positive")
    if k <= 0:
        return 0
    return d * ((k + d - 1) // d)


def read_dyad(k: int) -> int:
    """Least power of two that is >= k, i.e. 2 ** ceil(log2 k)."""
    if k <= 1:
        return 1
    e = 0
    while (1 << e) < k:
        e += 1
    return 1 << e


def resolves_arith(d: int, k: int) -> bool:
    """A step-d sweep reports k exactly iff d divides k."""
    return k % d == 0


def resolves_dyad(k: int) -> bool:
    """A doubling sweep reports k exactly iff k has binary weight one."""
    return bin(k).count("1") == 1


def overstatement(read_value: int, k: int) -> int:
    """How many budgets the sweep adds to the truth."""
    return read_value - k

from fractions import Fraction
from typing import Callable, Sequence


def sweep_and_read(
    f: Callable[[int], Fraction], tau: Fraction, sweep: Sequence[int]
) -> int:
    """Least swept budget clearing the gate, found in ceil(log2 r) oracle calls."""
    pts = sorted(sweep)
    if not pts or f(pts[-1]) < tau:
        raise ValueError("gate not cleared at any swept budget")
    lo, hi = -1, len(pts) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if f(pts[mid]) >= tau:
            hi = mid
        else:
            lo = mid
    return pts[hi]

