    sort S increasingly as g[1] < ... < g[r]
    i <- least index with f(g[i]) >= tau        # exists, else no certificate
    low  <- (i = 1) ? 0 : g[i-1]                # last failing swept point
    high <- g[i]                                # reported knee = read_S(k*)
    candidates <- { t : low < t <= high }       # all knees consistent with data
