from fractions import Fraction
from typing import Callable, List, Sequence, Tuple


def bracket_certificate(
    f: Callable[[int], Fraction], tau: Fraction, sweep: Sequence[int]
) -> Tuple[int, int, List[int]]:
    """Return (last failing point, reported knee, all consistent true knees)."""
    pts = sorted(sweep)
    for i, g in enumerate(pts):
        if f(g) >= tau:
            low = 0 if i == 0 else pts[i - 1]
            return low, g, list(range(low + 1, g + 1))
    raise ValueError("gate not cleared at any swept budget")


def strictness_certified(
    bracket_a: Tuple[int, int], bracket_b: Tuple[int, int]
) -> bool:
    """Do two brackets (lo, hi] force k*_a < k*_b?"""
    return bracket_a[1] <= bracket_b[0]

