function DESIGN_SWEEP(K, N):
    d <- 0
    for k in K: d <- gcd(d, k)              # Euclid, O(|K| log max K)
    sweep <- { d, 2d, 3d, ... } intersect (0, N]
    cost  <- floor(N / d)

    dyadic_resolvable <- { k in K : binary digit sum of k = 1 }
    dyadic_verdicts   <- ceil(log2 N) + 1
    certifiable_increases <- (number of distinct octaves met by K) - 1

    return (d, sweep, cost, dyadic_resolvable, dyadic_verdicts,
            certifiable_increases)
